Definition pch_atbd4_stmt : Prop :=
  forall rax ra sp gp tp t0x t1x a0 a1 a2 a3 a4 a5 a6 a7 s6x s8x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (p t : Z) (g : bool) (j16 junk : list byte),
  pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs p
          [CB 16 j16; C8 (shw (P + 76))] [C8 (wz 0); C8 (wz 0); C8 (wz 0)] g junk ->
  pch_pure sp P IN E lo shi c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  p0 <= p <= p0 + Z.of_nat (length bs) ->
  (t = 0 \/ (p + 2 <= t <= p0 + Z.of_nat (length bs)
             /\ exists bq, nth_error bs (Z.to_nat (t - 2 - p0)) = Some bq /\ zb bq = 13)) ->
