                (wz (p0 + Z.of_nat (length bs))) s6x (wz (Z.of_nat (length bs))) s8x t3 t4 t5 t6 P IN E)
        F (Z_to_bv 64 0xd2a54) fc None m1 (seg_rom bsegs)).
