Definition pch_go_stmt : Prop :=
  forall rax ra sp gp tp t0x t1x t2 a0 a1 a3 a4 a6 a7 s6x s8x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (p sk : Z) (e1 e2 e3 : word) (g : bool) (j24 junk : list byte),
  pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs p
          [CB 24 j24] [C8 e1; C8 e2; C8 e3] g junk ->
  pch_pure sp P IN E lo shi c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  p0 <= p -> 0 <= sk -> p + sk <= p0 + Z.of_nat (length bs) ->
  evt bsegs (pch_postI ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m)
    (MS (pch_ms rax sp gp tp t0x t1x t2 a0 a1 (wz sk) a3 a4 (shw (P + 76)) a6 a7
                (wz (p0 + Z.of_nat (length bs))) s6x (wz (Z.of_nat (length bs))) s8x t3 t4 t5 t6 P IN E)
        F (Z_to_bv 64 0xd2898) fc None m1 (seg_rom bsegs)).

